<?php if (!($data['preview'] ?? false)) { require __DIR__ . '/live/trip.php'; return; } ?>
<?php
use App\UI\UI as U;
$trips=$data['sample']['trips']; $queryTrip=$_GET['trip']??'08';
$trip=is_string($queryTrip) && array_key_exists($queryTrip,$trips)?$queryTrip:'08'; $t=$trips[$trip];
$load=array_sum(array_column($t['stops'],2)); $delivered=array_values(array_filter($t['stops'],fn($stop)=>$stop[3]==='Delivered')); // shortcut: sample stops carry no distance, so each uses the 1-3 km fee; use each address's km once orders come from the database.
$fee=\App\UI\Products::deliveryFee(1.5);
$cash=array_sum(array_column($delivered,2))*\App\UI\Products::get('round')['price']+count($delivered)*$fee;
$rows=[]; foreach($t['stops'] as $i=>$stop) $rows[]=[$i+1,U::e($stop[0]),U::e($stop[1]),$stop[2],U::badge($stop[3],$stop[3]==='Delivered'?'green':'blue')];
?>
<?= U::heading('Trip '.$trip,''.$info['caption'].' · November 2, 2026',U::btn('Back to deliveries','/station-admin/deliveries','secondary','arrow-left')) ?>
<div class="grid gap-5 xl:grid-cols-[minmax(0,1fr)_340px]"><div class="space-y-5"><section class="panel p-5"><div class="mb-5 flex justify-between gap-3"><?= U::title('Delivery stops','truck','') ?><?= U::badge($t['status'],$t['status']==='Completed'?'green':'blue') ?></div><?= U::table(['Stop','Order','Customer','Containers','Status'],$rows) ?></section><section class="panel p-5"><?= U::title('Trip timeline','truck','') ?><ol class="mt-5 space-y-5 border-l-2 border-line pl-5"><li><p class="font-bold">10:00 AM · Dispatched</p><p class="muted"><?= $load ?> containers loaded at the station.</p></li><li><p class="font-bold">10:18 AM · First stop completed</p><p class="muted"><?= $t['stops'][0][2] ?> containers delivered. <?= U::money($t['stops'][0][2]*\App\UI\Products::get('round')['price']+$fee) ?> collected.</p></li><li><p class="font-bold"><?= $t['status']==='Completed'?'11:02 AM · Trip completed':($t['status']==='Returning'?'10:50 AM · Returning to station':'10:25 AM · En route to next stop') ?></p><p class="muted"><?= $t['status']==='Completed'?'Driver returned to station.':($t['status']==='Returning'?'All delivery stops completed.':'Driver is delivering in '.$t['area'].'.') ?></p></li></ol></section></div><aside class="panel h-fit p-5"><?= U::title('Trip summary','truck','') ?><div class="my-5 flex items-center gap-3"><?= U::avatar($t['initials']) ?><div><strong><?= U::e($t['driver']) ?></strong><p class="muted">Assigned driver</p></div></div><dl class="space-y-4"><div class="flex justify-between"><dt>Barangay</dt><dd><?= U::e($t['area']) ?></dd></div><div class="flex justify-between"><dt>Load</dt><dd><?= $load ?> / <?= $t['capacity'] ?> containers</dd></div><div class="flex justify-between"><dt>Stops completed</dt><dd><?= count($delivered) ?> / <?= count($t['stops']) ?></dd></div><div class="flex justify-between"><dt>Cash collected</dt><dd><?= U::money($cash) ?></dd></div></dl><div class="mt-5 border-t border-line pt-5"><p class="muted mb-3">Cash reconciliation is reviewed after the rider returns.</p><?= U::btn('Review delivery report','/station-admin/reports/deliveries','secondary','chart') ?></div></aside></div>
